<?php
require_once '../../../config/sesion.php'; verificarAdmin(); require_once '../../../controllers/LearningController.php'; require_once '../../../includes/learning_helpers.php';
$learning=new LearningController(); $idCurso=(int)($_GET['curso']??$_POST['id_curso']??0); $curso=$learning->buscarCurso($idCurso); if(!$curso){header('Location:listar.php');exit;} $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verificarCsrfPost();$accion=$_POST['accion']??'';try{if($accion==='guardar_eval'){$learning->guardarEvaluacion($idCurso,$_POST);}else{$evalActual=$learning->evaluacionCurso($idCurso,false);if(!$evalActual)throw new RuntimeException('Primero guarda la configuración de la evaluación.');if($accion==='agregar_pregunta')$learning->agregarPregunta((int)$evalActual['id_evaluacion'],$_POST);elseif($accion==='eliminar_pregunta')$learning->eliminarPregunta((int)$_POST['id_pregunta'],(int)$evalActual['id_evaluacion']);}header('Location:editar.php?curso='.$idCurso.'&ok=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$eval=$learning->evaluacionCurso($idCurso,false); $preguntas=$eval?$learning->preguntasEvaluacion((int)$eval['id_evaluacion']):[];
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evaluación - Learning Lab</title><link rel="stylesheet" href="../../../assets/css/admin.css"></head><body><?php include '../../includes/sidebar.php'; ?><div class="admin-main"><?php include '../../includes/navbar.php'; ?><section class="admin-content learning-admin-page"><div class="gestion-header"><div><span class="learning-admin-kicker">Evaluación final</span><h1><?php echo learningH($curso['titulo']); ?></h1><p class="dashboard-subtitle">La evaluación se desbloquea cuando el usuario completa todas las lecciones obligatorias.</p></div><a class="btn-limpiar" href="listar.php">Volver</a></div><?php if(isset($_GET['ok'])): ?><div class="mensaje-exito">Evaluación actualizada.</div><?php endif; ?><?php if($error): ?><div class="mensaje-error"><?php echo learningH($error); ?></div><?php endif; ?>
<div class="learning-admin-two-cols"><section class="dashboard-section"><span class="learning-admin-kicker">Configuración</span><h2>Examen final</h2><form method="POST" class="admin-form learning-compact-form"><?php echo csrfInput(); ?><input type="hidden" name="accion" value="guardar_eval"><input type="hidden" name="id_curso" value="<?php echo $idCurso; ?>"><label>Título</label><input name="titulo" required value="<?php echo learningH($eval['titulo']??('Evaluación final - '.$curso['titulo'])); ?>"><label>Descripción</label><textarea name="descripcion" rows="3"><?php echo learningH($eval['descripcion']??''); ?></textarea><div class="learning-inline-fields"><div><label>Nota mínima (%)</label><input type="number" min="0" max="100" step="1" name="nota_minima" value="<?php echo learningH($eval['nota_minima']??70); ?>"></div><div><label>Intentos permitidos</label><input type="number" min="1" max="20" name="intentos_permitidos" value="<?php echo (int)($eval['intentos_permitidos']??3); ?>"></div></div><label>Estado</label><select name="estado"><option value="borrador" <?php echo ($eval['estado']??'borrador')==='borrador'?'selected':''; ?>>Borrador</option><option value="publicada" <?php echo ($eval['estado']??'')==='publicada'?'selected':''; ?>>Publicada</option></select><button class="btn-editar">Guardar configuración</button></form></section>
<section class="dashboard-section"><span class="learning-admin-kicker">Banco de preguntas</span><h2>Nueva pregunta</h2><?php if(!$eval): ?><div class="admin-empty-state">Guarda primero la configuración del examen.</div><?php else: ?><form method="POST" class="admin-form learning-compact-form"><?php echo csrfInput(); ?><input type="hidden" name="accion" value="agregar_pregunta"><input type="hidden" name="id_curso" value="<?php echo $idCurso; ?>"><label>Pregunta</label><textarea name="pregunta" rows="3" required></textarea><div class="learning-inline-fields"><div><label>Tipo</label><select name="tipo" id="learningTipoPregunta"><option value="opcion_multiple">Opción múltiple</option><option value="verdadero_falso">Verdadero / Falso</option></select></div><div><label>Puntos</label><input type="number" name="puntos" min="0.1" step="0.1" value="1"></div><div><label>Orden</label><input type="number" name="orden" min="1" value="<?php echo count($preguntas)+1; ?>"></div></div><div class="learning-mc-options" id="learningMcOptions"><?php for($x=1;$x<=4;$x++): ?><div class="learning-option-input"><input type="radio" name="correcta" value="<?php echo $x; ?>" <?php echo $x===1?'checked':''; ?>><input name="opcion_<?php echo $x; ?>" placeholder="Opción <?php echo $x; ?>" <?php echo $x<=2?'required':''; ?>></div><?php endfor; ?></div><div class="learning-vf-options" id="learningVfOptions" hidden><label><input type="radio" name="respuesta_vf" value="verdadero" checked> Verdadero</label><label><input type="radio" name="respuesta_vf" value="falso"> Falso</label></div><button class="btn-crear">Agregar pregunta</button></form><?php endif; ?></section></div>
<section class="dashboard-section learning-section-gap"><div class="dashboard-section-header"><div><span class="learning-admin-kicker">Preguntas configuradas</span><h2><?php echo count($preguntas); ?> preguntas</h2></div></div><?php if(!$preguntas): ?><div class="admin-empty-state">Aún no hay preguntas.</div><?php else: ?><div class="learning-question-admin-list"><?php foreach($preguntas as $p): ?><article class="learning-question-admin"><div class="learning-question-num"><?php echo (int)$p['orden']; ?></div><div><strong><?php echo learningH($p['pregunta']); ?></strong><small><?php echo $p['tipo']==='verdadero_falso'?'Verdadero/Falso':'Opción múltiple'; ?> · <?php echo learningH($p['puntos']); ?> pts</small><div class="learning-admin-options"><?php foreach($p['opciones'] as $o): ?><span class="<?php echo $o['es_correcta']?'is-correct':''; ?>"><?php echo $o['es_correcta']?'✓ ':''; ?><?php echo learningH($o['texto']); ?></span><?php endforeach; ?></div></div><form method="POST" onsubmit="return confirm('¿Eliminar esta pregunta?');"><?php echo csrfInput(); ?><input type="hidden" name="accion" value="eliminar_pregunta"><input type="hidden" name="id_curso" value="<?php echo $idCurso; ?>"><input type="hidden" name="id_pregunta" value="<?php echo (int)$p['id_pregunta']; ?>"><button class="btn-eliminar">Eliminar</button></form></article><?php endforeach; ?></div><?php endif; ?></section>
</section></div><script>const t=document.getElementById('learningTipoPregunta'),mc=document.getElementById('learningMcOptions'),vf=document.getElementById('learningVfOptions');if(t){const sync=()=>{const isV=t.value==='verdadero_falso';mc.hidden=isV;vf.hidden=!isV;mc.querySelectorAll('input[type=text],input:not([type])').forEach((x,i)=>x.required=!isV&&i<2)};t.addEventListener('change',sync);sync();}</script></body></html>
